/// Central, build-time + run-time configuration for EduLanka.
///
/// Everything here is safe to commit - no secrets live in this file.
/// Firebase credentials are read from `lib/firebase_options.dart` (generated by
/// the FlutterFire CLI and **git-ignored**).
class AppConfig {
  AppConfig._();

  /// Shown in the splash screen, drawer and About page.
  static const String appName = 'EduLanka';

  /// Legal/help links. Replace with your own before publishing to Play Store.
  static const String privacyPolicyUrl = 'https://edulanka.example/privacy';
  static const String sourceCodeUrl = 'https://github.com/Rusindu12/1018';
  static const String contactEmail = 'hello@edulanka.example';

  // ------------------------------------------------------------------ firestore
  /// Firestore collection names.
  /// MUST stay in sync with `admin_web/app.js` and `firebase/firestore.rules`.
  static const String booksCollection = 'books';
  static const String papersCollection = 'papers';

  /// Firestore Storage folder for PDFs / covers.
  static const String storagePdfFolder = 'pdfs';
  static const String storageCoverFolder = 'covers';

  /// Page size for pagination ("load 20 items at a time").
  static const int pageSize = 20;

  // ------------------------------------------------------------------ fetching
  // The catalogue is read in bulk and cached (see docs/FIREBASE_SETUP.md for
  // why): it keeps the app working with ZERO custom Firestore indexes, makes
  // Sinhala/Tamil substring search possible without a paid search service and
  // lets the whole catalogue be browsed offline after the first launch.
  //
  // A Firestore query can only fetch [firestorePageSize] documents at a time,
  // so a big catalogue is streamed in chunks up to [maxCatalogDocuments].
  static const int firestorePageSize = 300;
  static const int maxCatalogDocuments = 2000;

  /// How long the cached catalogue is considered fresh. Within this window the
  /// app reads 0 Firestore documents; a pull-to-refresh always bypasses it.
  static const Duration catalogCacheTtl = Duration(hours: 12);

  /// Prefix for URLs served from `assets/` instead of the network. Used by the
  /// bundled demo catalogue so the app is fully usable with no backend at all.
  static const String assetScheme = 'asset:';

  /// Sample PDF shipped with the app (demo mode / offline PDF viewer smoke test).
  static const String samplePdfAsset = 'assets/sample/sample_paper.pdf';

  // ------------------------------------------------------------------ demo mode
  /// `--dart-define=FORCE_DEMO=true` always runs the bundled sample catalogue.
  static const bool forceDemo = bool.fromEnvironment('FORCE_DEMO');

  /// Set to `true` by bootstrap() in main.dart once Firebase is initialised with
  /// a real project. While false the app serves `assets/data/demo_*.json`, so a
  /// fresh clone runs (and looks complete) before any Firebase setup.
  static bool firebaseReady = false;

  /// Human readable reason shown on the Settings > Data source tile.
  static String firebaseStatus = 'Not initialised';

  /// True when the bundled offline catalogue is being used.
  static bool get demoMode => forceDemo || !firebaseReady;

  // ------------------------------------------------------------------ transfers
  /// Hard timeout for PDF downloads.
  static const Duration downloadTimeout = Duration(minutes: 5);

  /// Cover images are small - keep their cache for 30 days.
  static const Duration coverCacheStalePeriod = Duration(days: 30);
  static const Duration coverCacheMaxAge = Duration(days: 60);

  /// Folder name (inside the app documents directory) holding downloaded PDFs.
  static const String downloadFolder = 'edulanka_downloads';

  // ------------------------------------------------------------------ search
  /// Debounce applied to the search field before hitting Firestore.
  static const Duration searchDebounce = Duration(milliseconds: 350);

  /// Maximum number of entries kept in "recent searches".
  static const int maxRecentSearches = 10;
}
